class SetupShiftOrMerge:
    def _list(self, sol):
        plan = canonical(sol)
        out = []
        for i in range(self.n):
            row = plan[i]
            for t in range(self.T):
                if not row[t]:
                    continue
                lo = max(0, t - self.window)
                hi = min(self.T - 1, t + self.window)
                for t2 in range(lo, hi + 1):
                    if t2 != t and not row[t2]:
                        out.append((i, t, t2, "shift"))
        if out:
            return out
        for i in range(self.n):
            row = plan[i]
            for t in range(self.T):
                if not row[t]:
                    continue
                hi = min(self.T - 1, t + self.window)
                for t2 in range(t + 1, hi + 1):
                    if row[t2]:
                        out.append((i, t, t2, "drop2"))
        if out:
            return out
        for i in range(self.n):
            for t in range(self.T):
                if not plan[i][t]:
                    out.append((i, -1, t, "add"))
        return out

    def apply(self, sol, m):
        i, a, b, kind = m
        plan = [list(r) for r in canonical(sol)]
        if kind == "shift":
            plan[i][a] = False
            plan[i][b] = True
        elif kind == "drop2":
            plan[i][a] = False
            plan[i][b] = False
        else:
            plan[i][b] = True
        return canonical(plan)
